/**
 * M3 Expressive runtime theming for the AxiomLab site.
 *
 * The 49 md.sys.color roles are generated by AxiomLab itself (see scheme.ts):
 * the seed is converted to AxiomLab LCh and every role is sampled at an M3
 * tone with a role-specific chroma factor, then gamut-mapped by AxiomLab.
 * No HCT, no Material Color Utilities, no lookup tables.
 */
import { buildAxiomScheme } from './scheme.js';
import { COLOR_ROLES, cssVar } from './color-roles.js';

export const DEFAULT_SEED = '#3b82f6';
const STORAGE_KEY = 'axiomlab-theme';
const HEX_RE = /^#?[0-9a-f]{6}$/i;

function normalizeHex(value: string) {
	const v = value.trim();
	return v.startsWith('#') ? v : `#${v}`;
}

class ThemeState {
	seed = $state(DEFAULT_SEED);
	dark = $state(false);

	colors = $derived(buildAxiomScheme(HEX_RE.test(this.seed) ? normalizeHex(this.seed) : DEFAULT_SEED, this.dark));

	restore() {
		if (typeof localStorage === 'undefined') return;
		try {
			const saved = JSON.parse(localStorage.getItem(STORAGE_KEY) ?? 'null') as
				| { seed?: string; dark?: boolean }
				| null;
			if (saved?.seed && HEX_RE.test(saved.seed)) this.seed = normalizeHex(saved.seed);
			if (typeof saved?.dark === 'boolean') this.dark = saved.dark;
		} catch {
			// storage blocked: keep defaults
		}
	}

	apply() {
		if (typeof document === 'undefined') return;
		const root = document.documentElement;
		root.classList.toggle('dark', this.dark);
		for (const role of COLOR_ROLES) root.style.setProperty(cssVar(role), this.colors[role]);
	}

	persist() {
		if (typeof localStorage === 'undefined') return;
		try {
			localStorage.setItem(STORAGE_KEY, JSON.stringify({ seed: this.seed, dark: this.dark }));
		} catch {
			// ignore
		}
	}

	toggleDark() {
		this.dark = !this.dark;
	}

	setSeed(value: string) {
		if (HEX_RE.test(value.trim())) this.seed = normalizeHex(value);
	}
}

export const theme = new ThemeState();
